async function api(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:{'X-Console-Token':token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw Error(data.error||'Request failed');return data}
function list(id,items){$(id).replaceChildren(...items.map(value=>{const item=document.createElement('li');item.textContent=value;return item}))}
function savedProfile(){if(!snapshot)return 'custom';for(const [profile,steps] of Object.entries({economy:[24,7,14,14,22,13,14,13,14,16],balanced:[36,10,22,22,34,20,22,20,22,24],quality:[56,16,34,34,52,32,34,32,36,40],'quota-saver':[18,5,10,10,16,9,10,9,10,12]})){if(Object.values(snapshot.roles).every((value,index)=>value.steps===steps[index]))return profile}return 'custom'}
function profileName(profile){return t(({economy:'profileEconomy',balanced:'profileBalanced',quality:'profileQuality','quota-saver':'profileMinimum',custom:'profileCustom'})[profile]||'profileCustom')}
function selectedProfile(){return $('profileExtra').value||$('profile').value}
function modelChangeCount(){return Number($('model').value.trim()!==(snapshot?.model||''))+[...document.querySelectorAll('[data-role]')].filter(input=>input.value.trim()!==(snapshot?.roles?.[input.dataset.role]?.model||'')).length}
function updateSummaries(){if(!snapshot)return;$('scopeHint').textContent=t($('target').value==='user'?'scopeUserHint':'scopeProjectHint');$('profileHint').textContent=t(({economy:'profileEconomyHint',balanced:'profileBalancedHint',quality:'profileQualityHint','quota-saver':'profileMinimumHint',custom:'profileCustomHint'})[selectedProfile()]);$('currentSummary').textContent=profileName(savedProfile());const changed=modelChangeCount();$('pendingSummary').textContent=profileName(selectedProfile())+(changed?' · '+t('modelChanges')(changed):'')}
function modelLabel(value){return value}
function supersededModel(value){return /\/gpt-5(?:[.\-]|$)/i.test(value)}
function selectableModels(catalog){return (catalog?.status==='connected'?catalog.models:[]).filter(value=>!supersededModel(value))}
function modelSourceKey(catalog){return catalog?.status==='connected'?'modelsConnected':'modelsMissing'}
function renderModelSelectors(){const available=selectableModels(modelCatalog);const sources=new Map();for(const value of available){const provider=value.split('/')[0];if(!sources.has(provider))sources.set(provider,[]);sources.get(provider).push(value)}for(const select of [$('model'),...document.querySelectorAll('[data-role]')]){const chosen=select.value;const items=[new Option(t('inheritModel'),'')];if(chosen&&!available.includes(chosen)){const current=document.createElement('optgroup');current.label=t('modelsCurrent');current.append(new Option(modelLabel(chosen),chosen));items.push(current)}for(const [provider,models] of sources){const group=document.createElement('optgroup');group.label=t('modelsGroup')+' · '+provider;for(const value of models)group.append(new Option(modelLabel(value),value));items.push(group)}select.replaceChildren(...items);select.value=chosen||''} $('modelSource').textContent=t(modelState);const names=modelCatalog?.status==='connected'?[...sources.keys()]:['OpenAI','Anthropic','Google','Other'];$('providerTiles').replaceChildren(...names.map(name=>{const tile=document.createElement('span');tile.className='provider-tile';const title=document.createElement('strong');title.textContent=name;const detail=document.createElement('small');detail.textContent=modelCatalog?.status==='connected'?String(sources.get(name)?.length||0):t('providerUnavailable');tile.append(title,detail);return tile}))}
async function refreshModels(explicit=false){$('modelSource').textContent=t('modelsLoading');try{const fresh=await api(explicit?'/api/models/refresh':'/api/models',explicit?{}:undefined);if(modelCatalog?.status==='connected'&&fresh.status!=='connected'){modelState='modelsRefreshFailed'}else{modelCatalog=fresh;teamCatalog=fresh;modelState=modelSourceKey(fresh)}renderModelSelectors();renderTeam()}catch(error){modelState='modelsRefreshFailed';renderModelSelectors();if(teamInfo)$('teamModelSource').textContent=t(modelState);if(explicit)showError(error)}}
function renderStatic(){$('restore').disabled=!snapshot?.restore_available;document.documentElement.lang=lang;document.title='Ustam · '+t('tabPreferences');for(const item of document.querySelectorAll('[data-i18n]'))item.textContent=t(item.dataset.i18n);for(const item of document.querySelectorAll('[data-i18n-aria]'))item.setAttribute('aria-label',t(item.dataset.i18nAria));for(const item of document.querySelectorAll('[data-i18n-placeholder]'))item.placeholder=t(item.dataset.i18nPlaceholder);for(const button of document.querySelectorAll('[data-lang]'))button.setAttribute('aria-pressed',String(button.dataset.lang===lang));for(const item of document.querySelectorAll('[data-role-name]'))item.textContent=t('roleName')[item.dataset.roleName]||item.dataset.roleName;$('taskModel').options[0].textContent=t('allModels');list('limits',[1,2,3,4].map(n=>t('limit'+n)));$('setup').textContent=snapshot?t(snapshot.installed?'setupInstalled':'setupMissing'):'';$('effective').textContent=snapshot?t('effectiveIntro')+'\n'+JSON.stringify({model:snapshot.effective.model,roles:snapshot.effective.roles},null,2):'';renderModelSelectors();updateSummaries();if(statusKey)status(statusKey);if(previewResult)renderPreview();renderUsage();renderWork();renderTeam();teamSaveStatus(teamSaveStateKey,teamSaveStateKind)}
async function load(){snapshot=await api('/api/settings?target='+$('target').value);$('path').textContent=snapshot.target;$('model').replaceChildren(new Option(t('inheritModel'),''),...(snapshot.model?[new Option(modelLabel(snapshot.model),snapshot.model)]:[]));$('model').value=snapshot.model||'';const current=savedProfile();$('profile').value=['economy','balanced','quality'].includes(current)?current:'balanced';$('profileExtra').value=['quota-saver','custom'].includes(current)?current:'';if(current==='quota-saver'||current==='custom'&&Object.values(snapshot.roles).some(value=>value.steps))$('advanced').open=true;$('roles').replaceChildren(...Object.entries(snapshot.roles).map(([role,values])=>{const label=document.createElement('label');const title=document.createElement('span');title.dataset.roleName=role;label.append(title);const select=document.createElement('select');select.dataset.role=role;select.append(new Option(t('inheritModel'),''),...(values.model?[new Option(modelLabel(values.model),values.model)]:[]));select.value=values.model||'';select.dataset.savedModel=values.model||'';label.append(select);return label}));previewed='';previewResult=null;$('save').disabled=true;$('review').hidden=true;clearError();renderStatic();status('loaded');void refreshModels()}
function settings(){if(!snapshot)throw Error(t('notLoaded'));return{revision:snapshot.revision,profile:selectedProfile(),model:$('model').value.trim(),roles:Object.fromEntries([...document.querySelectorAll('[data-role]')].map(input=>[input.dataset.role,{model:input.value.trim()}])),allow_mixed:$('mixed').checked,replace:$('replace').checked}}
function action(fn){return async()=>{try{clearError();await fn()}catch(error){showError(error)}}}
function invalidatePreview(){previewed='';previewResult=null;$('save').disabled=true;$('review').hidden=true;updateSummaries()}
function renderPreview(){if(!previewResult)return;$('review').hidden=false;$('reviewSummary').textContent=previewResult.fields?t('reviewChange')(previewResult.fields,$('currentSummary').textContent,$('pendingSummary').textContent):t('reviewNone');$('diff').textContent=previewResult.diff}
$('target').onchange=action(load);$('modelRefresh').onclick=action(async()=>refreshModels(true));$('settings').addEventListener('input',invalidatePreview);$('settings').addEventListener('change',invalidatePreview);$('profile').addEventListener('change',()=>{$('profileExtra').value='';updateSummaries()});$('profileExtra').addEventListener('change',updateSummaries);
$('preview').onclick=action(async()=>{status('checking');const payload=settings();previewResult=await api('/api/preview',{target:$('target').value,settings:payload});previewed=JSON.stringify(payload);$('save').disabled=!previewResult.fields;renderPreview();status(previewResult.fields?'prepared':'noChanges')});
$('save').onclick=action(async()=>{status('saving');const payload=settings();if(JSON.stringify(payload)!==previewed)throw Error(t('previewAgain'));await api('/api/save',{target:$('target').value,settings:payload});await load();status('saved')});
