async function inspectTeam(){const info=await api('/api/team/inspect',{project:$('teamProject').value});teamInfo=info;teamCatalog=modelCatalog?.status==='connected'?modelCatalog:info.models;modelCatalog=teamCatalog;modelState=modelSourceKey(teamCatalog);renderModelSelectors();teamDraft=(info.team?.length?info.team:[teamDefault(0)]).map(item=>({...item}));$('teamProject').value=info.project;$('teamCount').value=String(teamDraft.length);$('teamProfile').value=info.profile||'balanced';teamChiefChoice=info.model||'';teamTask='';teamTaskBefore=null;teamPage=0;selectedTeamSlot=-1;renderTeam();invalidateTeam();teamStatusKey=info.installed?'teamOpened':'teamQuickStart';$('teamState').textContent=t(teamStatusKey);if(!info.installed){document.querySelector('[data-tab="teamSetup"]').click()}}
$('teamInspect').onclick=action(inspectTeam);$('teamModelRefresh').onclick=action(async()=>refreshModels(true));
function changeTeamCount(delta){const current=Number($('teamCount').value);const next=Math.max(1,Math.min(TEAM_MAX,current+delta));if(next===current)return;$('teamCount').value=String(next);while(teamDraft.length<next)teamDraft.push(teamDefault(teamDraft.length));if(next>current)teamPage=Math.floor((next-1)/TEAM_PAGE);renderTeam();invalidateTeam()}
$('teamCountDown').onclick=()=>changeTeamCount(-1);$('teamCountUp').onclick=()=>changeTeamCount(1);
$('teamCountEntry').onchange=()=>{const value=Number($('teamCountEntry').value);if(!Number.isInteger(value)||value<1||value>TEAM_MAX){$('teamCountEntry').value=$('teamCount').value;return}const old=Number($('teamCount').value);$('teamCount').value=String(value);while(teamDraft.length<value)teamDraft.push(teamDefault(teamDraft.length));if(value!==old){teamPage=Math.floor((value-1)/TEAM_PAGE);renderTeam();invalidateTeam()}};
$('teamPagePrev').onclick=()=>{teamPage=Math.max(0,teamPage-1);renderTeam()};$('teamPageNext').onclick=()=>{teamPage=Math.min(Math.ceil(Number($('teamCount').value)/TEAM_PAGE)-1,teamPage+1);renderTeam()};
$('teamChiefActor').onclick=()=>{selectedTeamSlot=-1;renderTeam()};
for(const id of ['teamReplace','teamMixed','teamProject']){$(id).addEventListener('change',invalidateTeam);$(id).addEventListener('input',invalidateTeam)}
$('teamMixed').addEventListener('change',renderTeamProviderHint);
$('teamPreview').onclick=async()=>{invalidateTeam();$('teamPreview').disabled=true;try{clearError();teamSaveStatus('checking','busy');if(!teamInfo)throw clientError('teamError');if(teamProviderIssue()&&!$('teamMixed').checked){$('teamAdvanced').open=true;throw clientError('teamProviderAction');}const request=teamPayload();const result=await api('/api/team/preview',request);teamPreviewed=JSON.stringify(request);$('teamSave').disabled=false;$('teamReviewBox').hidden=false;$('teamReviewSummary').textContent=t(teamInfo.installed?'teamPreparedUpdate':'teamPrepared')(result.fields);list('teamActions',result.actions);teamStatusKey='teamPrepared';teamStatusCount=result.fields;$('teamState').textContent=t(teamInfo.installed?'teamPreparedUpdate':'teamPrepared')(teamStatusCount);teamSaveStatus('prepared')}catch(error){showError(error);$('teamAdvanced').open=true;teamSaveStatus(error?.uiCode||errorSummary(String(error?.message||error)),'error')}finally{$('teamPreview').disabled=false}};
$('closeConsole').onclick=action(async()=>{await api('/api/close',{});status('consoleClosed')});
$('teamSave').onclick=async()=>{try{clearError();const request=teamPayload();if(JSON.stringify(request)!==teamPreviewed)throw clientError('previewAgain');$('teamSave').disabled=true;teamSaveStatus('saving','busy');await api('/api/team/save',request);await inspectTeam();await load();teamStatusKey='teamSaved';$('teamState').textContent=t(teamStatusKey);status('teamSaved');teamSaveStatus('teamSaved','success')}catch(error){invalidateTeam();showError(error);$('teamAdvanced').open=true;teamSaveStatus(error?.uiCode||errorSummary(String(error?.message||error)),'error')}};
$('teamUninstallConfirm').onchange=()=>{$('teamUninstallApply').disabled=!uninstallPreview||!$('teamUninstallConfirm').checked};
$('teamUninstallPreview').onclick=async()=>{
 $('teamUninstallPreview').disabled=true;$('teamUninstallCancel').disabled=false;uninstallPreview=null;uninstallDone=false;$('teamUninstallReview').hidden=true;$('teamUninstallConfirm').checked=false;$('teamUninstallApply').disabled=true;
 try{clearError();uninstallStatus('checking','busy');if(!teamInfo?.installed)throw clientError('teamError');uninstallPreview=await api('/api/team/uninstall/preview',{project:$('teamProject').value});$('teamUninstallReview').hidden=false;renderUninstall();uninstallStatus('teamUninstallReady')}
 catch(error){showError(error);$('teamUninstallState').textContent=String(error?.message||error);$('teamUninstallState').dataset.kind='error'}
 finally{$('teamUninstallPreview').disabled=false}
};
$('teamUninstallCancel').onclick=async()=>{
 uninstallPreview=null;$('teamUninstallReview').hidden=true;$('teamUninstallConfirm').checked=false;$('teamUninstallApply').disabled=true;
 try{await api('/api/team/uninstall/cancel',{project:$('teamProject').value});uninstallStatus('teamUninstallCancelled')}
 catch(error){showError(error);$('teamUninstallState').textContent=String(error?.message||error);$('teamUninstallState').dataset.kind='error'}
};
$('teamUninstallApply').onclick=async()=>{
 if(!uninstallPreview||!$('teamUninstallConfirm').checked)return;
 $('teamUninstallApply').disabled=true;$('teamUninstallPreview').disabled=true;
 try{clearError();uninstallStatus('removing','busy');const preview=uninstallPreview;const result=await api('/api/team/uninstall/confirm',{project:preview.project,preview_id:preview.preview_id,confirm:true});uninstallPreview={actions:result.actions};uninstallDone=true;$('teamUninstallPreview').disabled=true;$('teamUninstallConfirm').disabled=true;$('teamUninstallCancel').disabled=true;uninstallStatus('teamUninstallDone','success');try{await inspectTeam();await load()}catch(error){showError(error)}renderUninstall()}
 catch(error){uninstallPreview=null;$('teamUninstallReview').hidden=true;showError(error);const raw=String(error?.message||error),stale=/Project changed; review removal again|Uninstall plan changed; review again|Removal preview expired; review again/.test(raw);$('teamUninstallState').textContent=t(stale?'teamUninstallStale':'teamUninstallCheck');$('teamUninstallState').dataset.kind='error';$('teamUninstallPreview').disabled=false}
};
const chiefMotionTargets={teamSetup:['#teamChiefActor .team-baton-arm','#teamChiefActor .team-note-one','#teamChiefActor .team-note-two'],usage:['#chiefButton .baton-arm','#chiefButton .note-one','#chiefButton .note-two']};
const chiefMotionPhases={};let chiefMotionLastSaved='';
function saveChiefMotion(tab){
 const targets=chiefMotionTargets[tab];if(!targets||$(tab).hidden)return;
 const times=targets.map(selector=>document.querySelector(selector)?.getAnimations()[0]?.currentTime??null);
 if(times.some(time=>time!==null)){chiefMotionPhases[tab]={times,at:performance.now()};chiefMotionLastSaved=tab}
}
function restoreChiefMotion(tab){
 const saved=chiefMotionPhases[tab]||chiefMotionPhases[chiefMotionLastSaved];if(!saved)return;
 requestAnimationFrame(()=>{
  if($(tab).hidden)return;
  const elapsed=performance.now()-saved.at;
  chiefMotionTargets[tab].forEach((selector,index)=>{
   const animation=document.querySelector(selector)?.getAnimations()[0];
   if(animation&&saved.times[index]!==null)animation.currentTime=saved.times[index]+elapsed;
  });
 });
}
for(const button of document.querySelectorAll('[data-tab]'))button.onclick=()=>{
 const next=button.dataset.tab;if(!$(next).hidden)return;
 for(const tab of Object.keys(chiefMotionTargets))saveChiefMotion(tab);
 for(const id of ['teamSetup','settings','usage','tasks'])$(id).hidden=id!==next;
 for(const item of document.querySelectorAll('[data-tab]'))item.setAttribute('aria-pressed',String(item===button));
 if(chiefMotionTargets[next])restoreChiefMotion(next);
};
for(const button of document.querySelectorAll('[data-lang]'))button.onclick=()=>{lang=button.dataset.lang;try{localStorage.setItem('opencode-console-language',lang)}catch{};renderStatic()};
renderStatic();action(load)();action(inspectTeam)();
